function adminInventory(){const products=D.admin.products||[];return `<div class="admin-split"><section class="member-card"><h3 class="admin-section-title">افزودن موجودی</h3><form id="adminAddInventory" class="member-form"><label>محصول<select name="product_id" required><option value="">انتخاب</option>${products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Variant ID <small>اختیاری</small><input name="variant_id" type="number"></label><label>آیتم‌ها<textarea name="content" required placeholder="هر خط یک اکانت/کد/لینک"></textarea></label><button class="mini-action primary" type="submit">افزودن به انبار</button></form></section><section class="member-card"><div class="member-card-head"><h3>آخرین آیتم‌های انبار</h3></div><div class="member-list">${(D.admin.inventory||[]).map(i=>`<div class="member-row"><div><b>#${i.id} • ${esc(i.product_name||('Product '+i.product_id))}</b><small>${esc(i.status)} ${i.variant_title?'• '+esc(i.variant_title):''}</small></div><button class="mini-action danger" data-admin-action="delete-inventory" data-id="${i.id}">حذف</button></div>`).join('')||'<div class="member-empty">انبار خالی است.</div>'}</div></section></div>`}
function adminCoupons(){return `<div class="admin-split"><section class="member-card"><h3 class="admin-section-title">کد تخفیف جدید</h3><form id="adminAddCoupon" class="member-form"><label>کد<input name="code" required></label><div class="member-form cols-2"><label>نوع<select name="type"><option value="percent">درصد</option><option value="fixed">مبلغ ثابت</option></select></label><label>مقدار<input name="value" type="number" min="0" required></label></div><div class="member-form cols-2"><label>حداقل سفارش<input name="min_order_amount" type="number" value="0"></label><label>حداکثر استفاده<input name="max_uses" type="number" value="0"></label></div><button class="mini-action primary" type="submit">ساخت کد</button></form></section><section class="member-card"><div class="member-card-head"><h3>کدهای تخفیف</h3></div><div class="member-list">${(D.admin.coupons||[]).map(c=>`<div class="member-row"><div><b>${esc(c.code)}</b><small>${esc(c.discount_type||c.type)} • ${num(c.discount_value||c.value)} • استفاده ${num(c.used_count||0)}/${num(c.max_uses||0)||'∞'}</small></div><div class="admin-item-actions"><button class="mini-action" data-admin-action="toggle-coupon" data-id="${c.id}">${Number(c.is_active)?'غیرفعال':'فعال'}</button><button class="mini-action danger" data-admin-action="delete-coupon" data-id="${c.id}">حذف</button></div></div>`).join('')||'<div class="member-empty">کدی نیست.</div>'}</div></section></div>`}
function adminWithdrawals(){return `<section class="member-card"><div class="member-card-head"><h3>درخواست‌های برداشت</h3></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>#</th><th>کاربر</th><th>مبلغ</th><th>اطلاعات</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${(D.admin.withdrawals||[]).map(w=>`<tr><td>${w.id}</td><td>${esc(w.first_name||w.username||w.telegram_id)}</td><td>${money(w.amount)}</td><td>${esc(w.card_info||'')}</td><td>${esc(w.status)}</td><td><button class="mini-action good" data-admin-action="withdraw" data-id="${w.id}" data-act="paid">تایید</button> <button class="mini-action danger" data-admin-action="withdraw" data-id="${w.id}" data-act="rejected">رد</button></td></tr>`).join('')||'<tr><td colspan="6">موردی نیست.</td></tr>'}</tbody></table></div></section>`}
function adminSettings(){const s=D.admin.settings||{},pm=s.payment_methods_enabled||{};return `<section class="member-card"><div class="member-card-head"><div><h3>تنظیمات فروشگاه و پرداخت</h3><p>تغییرات مستقیماً روی Storefront و Mini App مشترک اعمال می‌شود.</p></div></div><form id="adminSettingsForm" class="member-form cols-2"><label>نام برند<input name="brand_name" value="${esc(s.brand_name||'BlueGate')}"></label><label>پشتیبانی<input name="support_username" value="${esc(s.support_username||'')}"></label><label class="form-wide">Hero title<input name="storefront_hero_title" value="${esc(s.storefront_hero_title||'')}"></label><label class="form-wide">Hero text<textarea name="storefront_hero_text">${esc(s.storefront_hero_text||'')}</textarea></label><label>قیمت هر Star (تومان)<input name="storefront_star_sell_per_unit_toman" type="number" step="0.01" value="${esc(s.storefront_star_sell_per_unit_toman||0)}"></label><label>حداقل برداشت<input name="min_withdraw" type="number" value="${esc(s.min_withdraw||0)}"></label><label>حداقل Stars<input name="storefront_stars_min" type="number" value="${esc(s.storefront_stars_min||50)}"></label><label>حداکثر Stars<input name="storefront_stars_max" type="number" value="${esc(s.storefront_stars_max||10000)}"></label><label>Step Stars<input name="storefront_stars_step" type="number" value="${esc(s.storefront_stars_step||25)}"></label><label>Presetها<input name="storefront_stars_presets" value="${esc((s.storefront_stars_presets||[]).join(','))}"></label><label class="form-wide">متن اطلاعیه<input name="storefront_announcement_text" value="${esc(s.storefront_announcement_text||'')}"></label><label class="form-wide">کارت‌ها (هر خط: عنوان|کارت|نام|شبا)<textarea name="card_accounts_text">${esc(s.card_accounts_text||'')}</textarea></label><label class="form-wide">ولت‌های کریپتو<textarea name="crypto_wallets_text">${esc(s.crypto_wallets_text||'')}</textarea></label><label class="form-wide">دستور پرداخت<textarea name="payment_instructions">${esc(s.payment_instructions||'')}</textarea></label><div class="form-wide member-card" style="padding:12px"><b style="font-size:10px">روش‌های پرداخت فعال</b><div class="member-actions"><label><input type="checkbox" name="pm_wallet" ${pm.wallet?'checked':''}> کیف پول</label><label><input type="checkbox" name="pm_card" ${pm.card?'checked':''}> کارت</label><label><input type="checkbox" name="pm_crypto" ${pm.crypto?'checked':''}> کریپتو</label><label><input type="checkbox" name="pm_stars" ${pm.stars?'checked':''}> Stars</label></div></div><button class="mini-action primary form-wide" type="submit">ذخیره تنظیمات</button></form></section>`}
function adminAdvanced(){return `<div class="member-grid-2"><section class="member-card"><div class="member-card-head"><h3>Broadcast</h3></div><form id="adminBroadcastForm" class="member-form"><label>پیام همگانی<textarea name="text" required></textarea></label><button class="mini-action primary" type="submit">ارسال به کاربران تلگرام</button></form></section><section class="member-card"><div class="member-card-head"><h3>Backup</h3></div><div class="member-actions"><button class="mini-action good" data-admin-action="backup-create">ساخت Backup</button></div><div class="member-list" style="margin-top:12px">${(D.admin.backups||[]).map(b=>`<div class="member-row"><div><b>${esc(b.filename||b.name||'backup')}</b><small>${esc(b.created_at||b.mtime||'')}</small></div><div class="admin-item-actions"><button class="mini-action" data-admin-action="backup-restore" data-name="${esc(b.filename||b.name||'')}">Restore</button><button class="mini-action danger" data-admin-action="backup-delete" data-name="${esc(b.filename||b.name||'')}">حذف</button></div></div>`).join('')||'<div class="member-empty">Backupی ثبت نشده.</div>'}</div></section><section class="member-card"><div class="member-card-head"><h3>کاربر / موجودی</h3></div><form id="adminBalanceForm" class="member-form cols-2"><label>Telegram ID<input name="telegram_id" type="number" required></label><label>تغییر موجودی<input name="amount" type="number" required placeholder="مثلاً 50000 یا -50000"></label><button class="mini-action" type="submit">اعمال موجودی</button></form><hr style="border:0;border-top:1px solid var(--line);margin:16px 0"><form id="adminUserLookup" class="member-form"><label>User ID داخلی<input name="user_id" type="number" min="1" required></label><button class="mini-action" type="submit">دریافت و ویرایش کاربر</button></form></section><section class="member-card"><div class="member-card-head"><h3>تنظیمات فنی</h3></div><div class="member-list"><div class="member-row"><b>آخرین Backup</b><span>${esc(D.admin.settings?.backup_last_created_at||'—')}</span></div><div class="member-row"><b>منبع نرخ کریپتو</b><span>${esc(D.admin.settings?.crypto_rate_source||'auto')}</span></div><div class="member-row"><b>تایید ایمیل</b><span>${D.admin.settings?.require_email_verification?'فعال':'غیرفعال'}</span></div></div></section></div>`}
function fileData(file,max=5*1024*1024){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve(null);if(file.size>max)return reject(new Error('حجم فایل بیشتر از حد مجاز است.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('خواندن فایل ناموفق بود.'));r.readAsDataURL(file)})}
async function userAction(action,id,extra={}){setBusy(true);try{let res;if(action==='pay-wallet')res=await api('apply_wallet',{order_id:id});if(action==='pay-card')res=await api('select_payment_method',{order_id:id,method:'card'});if(action==='pay-stars')res=await api('start_stars_invoice',{order_id:id});if(res?.user)D.data=res;else await refresh();toast('انجام شد.','success');renderOrders()}catch(e){toast(e.message,'error')}finally{setBusy(false)}}
async function adminCall(action,body={},success='ذخیره شد.'){setBusy(true);try{const res=await api(action,body);if(res.report||res.products||res.orders)D.admin=res;else D.admin=await api('admin_summary');toast(success,'success');renderAdminPane()}catch(e){toast(e.message,'error')}finally{setBusy(false)}}
function formObj(form){const f=new FormData(form),o={};for(const [k,v] of f.entries())o[k]=v;return o}
async function handleSubmit(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;if(!f.closest('#memberApp'))return;e.preventDefault();try{setBusy(true);if(f.id==='withdrawForm'){D.data=await api('withdraw',{card_info:new FormData(f).get('card_info')});toast('درخواست برداشت ثبت شد.','success');renderWallet()}
else if(f.id==='customCodeForm'){D.data=await api('custom_code',{code:new FormData(f).get('code')});D.referrals=null;toast('کد دعوت بروزرسانی شد.','success');renderReferral()}
else if(f.id==='themeColorForm'){D.data=await api('set_user_color',{theme_color:new FormData(f).get('theme_color')});toast('رنگ ذخیره شد.','success');renderProfile()}
else if(f.classList.contains('coupon-form')){D.data=await api('apply_coupon',{order_id:Number(f.dataset.id),code:new FormData(f).get('code')});toast('کد اعمال شد.','success');renderOrders()}
else if(f.classList.contains('receipt-form')){const fd=new FormData(f),b64=await fileData(fd.get('receipt'));D.data=await api('submit_receipt',{order_id:Number(f.dataset.id),note:fd.get('note'),receipt_b64:b64});toast('رسید ارسال شد.','success');renderOrders()}
else if(f.classList.contains('crypto-hash-form')){const fd=new FormData(f);D.data=await api('submit_crypto_hash',{order_id:Number(f.dataset.id),tx_hash:fd.get('tx_hash')});toast('TXID ثبت شد.','success');renderOrders()}
else if(f.id==='adminAddProduct'){const o=formObj(f);o.is_featured=0;await adminCall('admin_add_product',o,'محصول ساخته شد.')}
else if(f.id==='adminAddCategory'){await adminCall('admin_add_category',formObj(f),'دسته ساخته شد.')}
else if(f.id==='adminAddInventory'){await adminCall('admin_add_inventory',formObj(f),'انبار بروزرسانی شد.')}
else if(f.id==='adminAddCoupon'){await adminCall('admin_add_coupon',formObj(f),'کد تخفیف ساخته شد.')}
else if(f.id==='adminSettingsForm'){const fd=new FormData(f),o=formObj(f);o.payment_methods_enabled={wallet:fd.has('pm_wallet'),card:fd.has('pm_card'),crypto:fd.has('pm_crypto'),stars:fd.has('pm_stars')};delete o.pm_wallet;delete o.pm_card;delete o.pm_crypto;delete o.pm_stars;o.storefront_announcement_enabled=1;await adminCall('admin_save_settings',o,'تنظیمات ذخیره شد.')}
else if(f.id==='adminBroadcastForm'){await adminCall('admin_broadcast',{text:new FormData(f).get('text')},'ارسال همگانی شروع شد.')}
else if(f.id==='adminBalanceForm'){await adminCall('admin_add_balance',formObj(f),'موجودی کاربر تغییر کرد.')}
else if(f.id==='adminUserLookup'){const uid=Number(new FormData(f).get('user_id'));const r=await api('admin_get_user',{user_id:uid}),u=r.user||{};const first_name=prompt('نام:',u.first_name||'');if(first_name===null)return;const last_name=prompt('نام خانوادگی:',u.last_name||'');if(last_name===null)return;const email=prompt('ایمیل:',u.email||'');if(email===null)return;const phone=prompt('شماره تماس:',u.phone_number||u.phone||'');if(phone===null)return;const web_username=prompt('نام کاربری وب:',u.web_username||u.username||'');if(web_username===null)return;const balance=prompt('موجودی فعلی:',String(u.balance||0));if(balance===null)return;await adminCall('admin_edit_user',{user_id:uid,first_name,last_name,email,phone,web_username,balance},'اطلاعات کاربر بروزرسانی شد.')}
else if(f.id==='adminOrderSearch'){const o=formObj(f),res=await api('admin_search_orders',o);$('adminOrdersList').innerHTML=(res.orders||[]).map(x=>orderCard(x,true)).join('')||'<div class="member-empty">نتیجه‌ای نیست.</div>'}
}catch(err){toast(err.message,'error')}finally{setBusy(false)}}
async function handleClick(e){const route=e.target.closest('[data-member-route]');if(route){e.preventDefault();go(route.dataset.memberRoute);return}const cp=e.target.closest('[data-copy]');if(cp){navigator.clipboard?.writeText(cp.dataset.copy||'');toast('کپی شد ✓','success');return}const at=e.target.closest('[data-admin-tab]');if(at){D.adminTab=at.dataset.adminTab;renderAdmin();return}const b=e.target.closest('[data-action]');if(b){const a=b.dataset.action;if(a==='store-home')go('home');if(a==='refresh'){await refresh();renderRoute();toast('بروزرسانی شد.','success')}if(a==='logout'){await BGApi.logout();D.data=null;D.admin=null;D.referrals=null;syncChrome();go('home');toast('از حساب خارج شدی.')}if(a==='delete-account'){if(confirm('حساب و اطلاعات مرتبط به‌صورت دائمی حذف شود؟')){await api('delete_my_account');BGApi.setToken('');D.data=null;go('home');toast('حساب حذف شد.','success')}}if(a==='pay-wallet'||a==='pay-card'||a==='pay-stars')await userAction(a,Number(b.dataset.id));if(a==='pay-crypto'){D.data=await api('select_payment_method',{order_id:Number(b.dataset.id),method:'crypto'});renderOrders()}if(a==='reset-payment'){D.data=await api('select_payment_method',{order_id:Number(b.dataset.id),method:'none'});renderOrders();toast('روش پرداخت بازنشانی شد.','success')}if(a==='select-crypto'){D.data=await api('start_crypto_payment',{order_id:Number(b.dataset.order),wallet_id:Number(b.dataset.wallet)});renderOrders();toast('ولت انتخاب شد.','success')}if(a==='check-crypto'){D.data=await api('check_crypto_payment',{order_id:Number(b.dataset.id)});renderOrders();toast('وضعیت تراکنش بررسی شد.','success')}if(a==='spin'){D.data=await api('spin');toast('🎁 '+esc(D.data.prize?.title||'جایزه ثبت شد'),'success');renderWallet()}if(a==='claim-missions'){D.data=await api('claim_missions');toast('ماموریت‌های قابل دریافت بررسی شد.','success');renderWallet()}if(a==='cancel-order'){if(confirm('این سفارش لغو شود؟')){D.data=await api('cancel_order',{order_id:Number(b.dataset.id)});renderOrders();toast('سفارش لغو شد.','success')}}if(a==='hide-order'){if(confirm('این سفارش از لیست شما حذف شود؟')){D.data=await api('hide_order',{order_id:Number(b.dataset.id)});renderOrders();toast('از لیست حذف شد.','success')}}if(a==='customer-note'){const note=prompt('یادداشت یا توضیح برای پشتیبانی:');if(note){D.data=await api('customer_order_note',{order_id:Number(b.dataset.id),note});renderOrders();toast('یادداشت ارسال شد.','success')}}if(a==='open-service'){await openServiceViewer(Number(b.dataset.id),b.dataset.title||'مدیریت سرویس')}return}
const ab=e.target.closest('[data-admin-action]');if(ab){const a=ab.dataset.adminAction,id=Number(ab.dataset.id||0);if(a==='refresh-admin'){D.admin=await api('admin_summary');renderAdminPane();toast('بروزرسانی شد.','success')}else if(a==='refresh-rates')await adminCall('admin_refresh_crypto_rates',{},'نرخ‌ها تازه شدند.')
else if(a==='order-status'){await adminCall('admin_order_status',{order_id:id,status:ab.dataset.status})}
else if(a==='service-delivery'){const url=prompt('لینک HTTPS پنل/ساب این سفارش:',ab.dataset.url||'https://');if(url===null)return;const title=prompt('عنوان دکمه برای مشتری:',ab.dataset.title||'مدیریت سرویس');if(title===null)return;const note=prompt('پیام تحویل (لینک اصلی در پیام نمایش داده نمی‌شود):','سرویس شما آماده است. برای مشاهده روی دکمه باز کردن سرویس بزنید.');if(note===null)return;await adminCall('admin_set_service_delivery',{order_id:id,delivery_url:url,delivery_title:title,delivery_note:note},'لینک امن سرویس ثبت و سفارش تحویل شد.')}
else if(a==='deliver-order'){const d=prompt('اطلاعات تحویل را وارد کن:');if(d)await adminCall('admin_deliver_order',{order_id:id,delivery:d},'سفارش تحویل شد.')}
else if(a==='order-note'){const n=prompt('یادداشت داخلی سفارش:',ab.dataset.note||'');if(n!==null)await adminCall('admin_order_note',{order_id:id,note:n})}
else if(a==='customer-view'){try{const c=await api('admin_customer_view',{user_id:Number(ab.dataset.user)});alert(`مشتری: ${c.user?.first_name||c.user?.username||c.user?.id}\nموجودی: ${money(c.user?.balance)}\nخرید تحویل‌شده: ${money(c.total_spent)}\nتعداد سفارش: ${(c.orders||[]).length}`)}catch(err){toast(err.message,'error')}}
else if(a==='toggle-product')await adminCall('admin_toggle_product',{product_id:id})
else if(a==='delete-product'){if(confirm('محصول غیرفعال/حذف نرم شود؟'))await adminCall('admin_delete_product',{product_id:id})}
else if(a==='edit-product'){const p=(D.admin.products||[]).find(x=>x.id===id);if(p){const name=prompt('نام محصول:',p.name);if(name===null)return;const price=prompt('قیمت تومان:',p.price);if(price===null)return;await adminCall('admin_update_product',{product_id:id,name,price,price_currency:'IRT'},'محصول ویرایش شد.')}}
else if(a==='add-variant'){const title=prompt('نام پلن/Variant:');if(!title)return;const price=prompt('قیمت تومان:','0');if(price===null)return;await adminCall('admin_add_variant',{product_id:id,title,price,price_currency:'IRT'},'پلن اضافه شد.')}
else if(a==='edit-variant'){const title=prompt('نام پلن:',ab.dataset.title||'');if(title===null)return;const price=prompt('قیمت:',ab.dataset.price||'0');if(price===null)return;await adminCall('admin_update_variant',{variant_id:id,title,price,price_currency:'IRT'},'پلن ویرایش شد.')}
else if(a==='delete-variant'){if(confirm('پلن غیرفعال شود؟'))await adminCall('admin_delete_variant',{variant_id:id})}
else if(a==='edit-category'){const c=(D.admin.categories||[]).find(x=>Number(x.id)===id)||{};const title=prompt('نام دسته:',ab.dataset.title||c.title||'');if(title===null)return;const emoji=prompt('ایموجی:',ab.dataset.emoji||c.emoji||'🛒');if(emoji===null)return;const sort_order=prompt('ترتیب نمایش (عدد کمتر = بالاتر):',String(c.sort_order??99));if(sort_order===null)return;await adminCall('admin_update_category',{category_id:id,title,emoji,sort_order:Number(sort_order||0)},'دسته بروزرسانی شد.')}
else if(a==='delete-category'){if(confirm('دسته غیرفعال شود؟'))await adminCall('admin_delete_category',{category_id:id},'دسته غیرفعال شد.')}
else if(a==='delete-inventory'){if(confirm('آیتم انبار حذف شود؟'))await adminCall('admin_delete_inventory',{inventory_id:id})}
else if(a==='toggle-coupon')await adminCall('admin_toggle_coupon',{coupon_id:id})
else if(a==='delete-coupon'){if(confirm('کد تخفیف حذف شود؟'))await adminCall('admin_delete_coupon',{coupon_id:id})}
else if(a==='withdraw')await adminCall('admin_withdraw_action',{withdrawal_id:id,action_type:ab.dataset.act},'وضعیت برداشت تغییر کرد.')
else if(a==='backup-create')await adminCall('admin_backup_create',{},'Backup ساخته شد.')
else if(a==='backup-restore'){if(confirm('هشدار: دیتابیس فعلی با این Backup جایگزین می‌شود. ادامه می‌دهی؟')){await adminCall('admin_backup_restore_server',{filename:ab.dataset.name,confirm:'RESTORE'},'Backup ریستور شد.');location.reload()}}
else if(a==='backup-delete'){if(confirm('Backup حذف شود؟'))await adminCall('admin_backup_delete',{filename:ab.dataset.name},'Backup حذف شد.')}
}}
async function init(){document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);window.addEventListener('hashchange',renderRoute);await ensureData();syncChrome();const oldOpen=BGAccount.open;BGAccount.open=function(mode='account'){if(logged()&&mode==='account'){go('account');return}oldOpen(mode)};const acc=$('accountBtn'),mob=$('mobileAccountBtn');if(acc){const clone=acc.cloneNode(true);acc.replaceWith(clone);clone.addEventListener('click',()=>logged()?go('account'):oldOpen('account'))}if(mob){const clone=mob.cloneNode(true);mob.replaceWith(clone);clone.addEventListener('click',()=>logged()?go('account'):oldOpen('account'))}await renderRoute()}
window.BGDashboard={init,go,renderRoute,refresh:async()=>{await refresh();await renderRoute()}};
